package temp

import (
	"math"
	"testing"
)

func almostEqual(a, b float64) bool { return math.Abs(a-b) < 1e-9 }

func TestCtoF(t *testing.T) {
	if !almostEqual(CtoF(0), 32) { t.Fatalf("CtoF(0) want 32, got %f", CtoF(0)) }
	if !almostEqual(CtoF(100), 212) { t.Fatalf("CtoF(100) want 212, got %f", CtoF(100)) }
}

func TestFtoC(t *testing.T) {
	if !almostEqual(FtoC(32), 0) { t.Fatalf("FtoC(32) want 0, got %f", FtoC(32)) }
	if !almostEqual(FtoC(212), 100) { t.Fatalf("FtoC(212) want 100, got %f", FtoC(212)) }
}

func TestCtoK(t *testing.T) {
	if !almostEqual(CtoK(0), 273.15) { t.Fatalf("CtoK(0) want 273.15, got %f", CtoK(0)) }
	if !almostEqual(CtoK(-273.15), 0) { t.Fatalf("CtoK(-273.15) want 0, got %f", CtoK(-273.15)) }
}
